$(function() {
    const e = $("#btnIngresar")
    e.on("click", function() {
      const t = $("#logina").val()
      const n = $("#clavea").val()
      function e(e) {
        try {
          typeof bootbox != "undefined"
            ? bootbox.alert({
                message: e,
                size: "small"
              })
            : alert(e)
        } catch (t) {
          alert(e)
        }
      }
      if (t.trim() == "" || n.trim() == "")
        return e("Los campos no pueden estar vac\xEDos"), false
      if (n.length < 5)
        return e("La contrase\xF1a debe tener al menos 5 caracteres"), false
      const o = /^[a-zA-Z0-9@._]+$/
      if (!o.test(t))
        return (
          e(
            "El usuario solo puede contener letras, n\xFAmeros y los caracteres @._"
          ),
          false
        )
      if (t.length > 50 || n.length > 50)
        return e("Los campos exceden la longitud m\xE1xima permitida"), false
      $.ajax({
        url: "../ajax/usuario.php?op=verificar",
        type: "POST",
        data: {
          logina: t,
          clavea: n,
          idusuario: sessionStorage.getItem("idusuario")
        },
        dataType: "json",
        success: function(t) {
          console.log("Respuesta del servidor:", t),
            "0" == t
              ? e("Usuario y/o Password incorrectos")
              : (sessionStorage.setItem("idusuario", t.idusuario),
                (window.location = "../vistas/seleccionagencia.php"))
        },
        error: function(t, n, o) {
          console.error("Error en la petici\xF3n:", o),
            e("Error al conectar con el servidor") 
        }
      })
    })
  })